import{_ as n,a as o,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语","description":"L49–L72 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语","description":"L49–L72 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-03/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 3 语法总结","summary":"L49–L72 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-03/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 3 单词与短语","link":"/life/english/new-concept/book-2/unit-03/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 3 语法总结 · 时间、原因与让步从句至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-03/grammar-part-02"},"next":{"text":"第二册：实践与进步 · 单元 3 单词与短语","link":"/life/english/new-concept/book-2/unit-03/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/grammar-part-03.md","filePath":"life/english/new-concept/book-2/unit-03/grammar-part-03.md"}'),i={name:"life/english/new-concept/book-2/unit-03/grammar-part-03.md"};function r(l,e,s,p,d,c){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-3-语法总结-·-非真实条件句至分词修饰与逻辑主语" tabindex="-1">第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语 <a class="header-anchor" href="#第二册-实践与进步-·-单元-3-语法总结-·-非真实条件句至分词修饰与逻辑主语" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 3 语法总结 · 非真实条件句至分词修饰与逻辑主语&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-03/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元复习与自测</a></p><h2 id="非真实条件句" tabindex="-1">非真实条件句 <a class="header-anchor" href="#非真实条件句" aria-label="Permalink to &quot;非真实条件句 {#非真实条件句}&quot;">​</a></h2><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：If the plan had succeeded ... would have opened ... 是过去未实现的假设；不能据此得出工程当时实际开放。</p><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：had not been repaired 是过去反事实的被动条件；would have stopped 是假设结果。否定条件不表示实际没有维修，恰恰在此暗示修过。</p><p><strong>L64 原创例句：</strong> If the earlier plan had succeeded, the route would have opened sooner.</p><p>如果早先的计划成功，这条线路本会更早开放。</p><p><strong>L71 原创例句：</strong> If the clock had not been repaired, it would have stopped that winter.</p><p>如果那座钟没有修过，它在那个冬天就会停摆。</p><p><strong>易错：</strong> would have open 缺少过去分词；have 后应为 opened。</p><p>would stopped 缺少 have；过去反事实结果要用 would have stopped。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-064">Lesson 64</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-071">Lesson 71</a></p><h2 id="动名词与动词搭配" tabindex="-1">动名词与动词搭配 <a class="header-anchor" href="#动名词与动词搭配" aria-label="Permalink to &quot;动名词与动词搭配 {#动名词与动词搭配}&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：insist on 后接动名词，avoid 后也接动名词但不加介词。两种动词都能接 -ing，不代表结构完全相同。</p><p><strong>L68 原创例句：</strong> My neighbour insisted on helping me carry the boxes.</p><p>邻居坚持要帮我搬箱子。</p><p><strong>易错：</strong> insist to help 应改为 insist on helping；avoid to answer 应为 avoid answering。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-068">Lesson 68</a></p><h2 id="不定式与目的" tabindex="-1">不定式与目的 <a class="header-anchor" href="#不定式与目的" aria-label="Permalink to &quot;不定式与目的 {#不定式与目的}&quot;">​</a></h2><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：was told to brake 是转述指令的被动结构；told 的主动句需要听者，不能写 The instructor told to brake 而省略对象。</p><p><strong>L69 原创例句：</strong> The learner was told to stop beside the yellow line.</p><p>教练要求学员停在黄线旁边。</p><p><strong>易错：</strong> brake 是刹车，break 是弄坏或休息；二者同音但拼写含义不同。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-069">Lesson 69</a></p><h2 id="分词修饰与逻辑主语" tabindex="-1">分词修饰与逻辑主语 <a class="header-anchor" href="#分词修饰与逻辑主语" aria-label="Permalink to &quot;分词修饰与逻辑主语 {#分词修饰与逻辑主语}&quot;">​</a></h2><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：Waving a flag 的逻辑主语必须是主句的人，不能接 The gate was opened 而让门成为挥旗者。分词状语可压缩同主语动作。</p><p>现在分词常表达主动或正在进行，过去分词常表达被动或完成，用作定语时可置于名词前或以短语形式置后。作状语时，分词的逻辑主语一般要与主句主语一致，否则容易出现悬垂结构。不能只按“现在”“过去”的名称判断时间，具体时态由主句和上下文决定。复杂句改成分词结构前，先确认两个动作的执行者和先后关系。本课应用：a car called ... 中 called 是过去分词后置定语，等于 that is called；它不是主句谓语，所以句子还需要 ran、reached 等谓语。</p><p><strong>L70 原创例句：</strong> Waving a red flag, the steward guided the visitors away.</p><p>工作人员挥着红旗，引导游客离开。</p><p><strong>L72 原创例句：</strong> A car called Silver Finch completed three test runs.</p><p>一辆名为“银雀”的车完成了三次试跑。</p><p><strong>易错：</strong> Waving a flag, the visitors were moved 会让逻辑主语变成游客，不一定符合想表达的意思。</p><p>A car called Silver Finch. 只是名词短语，不构成完整陈述句。</p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">Lesson 70</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-072">Lesson 72</a></p>',35)])])}const u=n(i,[["render",r]]);export{g as __pageData,u as default};
